INSERT INTO `ok_okaycms__faq__faq` (`id`, `question`, `answer`, `visible`, `position`) VALUES
(1,	'ЧТО ДЕЛАТЬ, ЕСЛИ ТОВАР НЕ ПОДОШЕЛ ПО ФОРМЕ, ЦВЕТУ ИЛИ РАЗМЕРУ И ДРУГИЕ ПРИЧИНЫ?',	'<p>В течение 14 дней от даты приобретения товара (не считая дату покупки) - Вы можете товар, который не использовался, сохранен товарный вид и потребительские свойства, и отсутствует в перечне товаров, не подлежащих обмену или возврату: Обменять на аналогичный без пересчета стоимости Обменять на любой другой с соответствующим перерасчетом стоимости Вернуть и получить уплаченные за него денежные средства Как оценить сохранность товарного вида: При хорошем освещении, без применения специальных средств, на товаре не должно быть видимых следов пользования в виде мелких царапин, потертостей, а тем более сколов, вмятин или трещин. Проще всего оценить сохранен ли товарный вид, ответив себе на вопрос: &laquo;Купил бы я этот товар в таком виде, как новый?\"</p>',	1,	1),
(2,	'КАКОЙ ГАРАНТИЙНЫЙ СРОК У МОЕГО ТОВАРА?',	'<p>Гарантийный срок товара исчисляется со дня его продажи. Он обычно указан в эксплуатационном документе на товар (гарантийном талоне, техническом паспорте, этикетке или в другом документе, прилагаемом к товару). &nbsp;На сайте производителя Вашего товара</p>',	1,	2),
(3,	'Осуществляете ли Вы доставку до квартиры и подъем на этаж?',	'<p>Пожалуйста, обратите внимание, что адресная доставка осуществляется до входа в здание.<br />Товары из раздела &laquo;Бытовая техника и интерьер&raquo;, крупногабаритные товары из разделов \"Фитнес\", и \"Детский мир\" (тренажеры, детские кроватки, детская мебель, матрасы и т. д.)доставляются до квартиры.<br />Стоимость ручного заноса в квартиру зависит от: габаритов техники, сложности подъема и наличия лифта (куда товар помещается в упаковке).</p>',	1,	3),
(4,	'Возможно ли купить товар в рассрочку?',	'<p>К сожалению, в данный момент возможности приобретать товары в рассрочку нет.<br />Вы можете оформить заказ на интересующий Вас товар, доступный у нас на сайте, в кредит<br />Также, если Вы являетесь клиентом ПриватБанка, мы можем предложить Вам рассмотреть вариант оформления заказа с помощью услуг &laquo;Мгновенная рассрочка&raquo; и &laquo;Оплата частями&raquo;</p>',	1,	4);
