INSERT INTO `ok_payment_methods` (`id`, `module`, `name`, `description`, `currency_id`, `settings`, `auto_submit`, `enabled`, `position`, `image`, `novaposhta_cost__cash_on_delivery`) VALUES
(6,	'OkayCMS/LiqPay',	'Оплата картой через Liqpay.com',	'<p>LiqPay &mdash; платежная система, позволяющая проводить оплату банковскими картами MasterСard и VISA, а также наличными через терминалы самообслуживания Приватбанка. Оплата возможна после входа в аккаунт через номер мобильного телефона.</p>',	4,	'a:2:{s:18:\"liq_pay_public_key\";s:0:\"\";s:19:\"liq_pay_private_key\";s:0:\"\";}',	0,	1,	14,	'liqpay_logo.png',	NULL),
(14,	'null',	'Оплата наличными курьеру',	'<p>Если вы не хотите предварительно оплачивать заказ, у вас есть возможность рассчитаться с курьером наличными в момент получения посылки. Чтобы процесс был максимально комфортным и для вас, и для курьера, рекомендуем заранее подготовить нужную сумму.</p>',	4,	'a:0:{}',	0,	1,	18,	'nalcourier.png',	NULL),
(18,	'null',	'Оплата наложенным платежом',	'<p>Оплата производится наложенным платежом после получения товара.</p>',	4,	'a:0:{}',	0,	1,	19,	'wallet.png',	1),
(20,	'OkayCMS/WayForPay',	'Оплата через WayForPay',	'<p>WayForPay &mdash; это онлайн-сервис с оплатой через банковские карты платежных систем VISA и MasterCard. Доступные методы платежа: Приват 24, терминал, сервис обслуживает прием платежей через систему Bitcoin.</p>',	4,	'a:2:{s:18:\"wayforpay_merchant\";s:0:\"\";s:19:\"wayforpay_secretkey\";s:0:\"\";}',	0,	1,	21,	'wayforpay.png',	NULL);
