DROP TABLE IF EXISTS `ok_orders`;
CREATE TABLE `ok_orders` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `delivery_id` int(11) DEFAULT 0,
  `delivery_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `payment_method_id` int(11) DEFAULT 0,
  `paid` tinyint(1) NOT NULL DEFAULT 0,
  `payment_date` datetime DEFAULT NULL,
  `closed` tinyint(1) NOT NULL DEFAULT 0,
  `date` datetime DEFAULT NULL,
  `user_id` int(11) DEFAULT 0,
  `name` varchar(255) NOT NULL DEFAULT '',
  `last_name` varchar(255) DEFAULT NULL,
  `address` varchar(255) NOT NULL DEFAULT '',
  `phone` varchar(32) DEFAULT '',
  `phone_to_delete` varchar(32) NOT NULL DEFAULT '',
  `email` varchar(255) NOT NULL DEFAULT '',
  `comment` varchar(1024) NOT NULL DEFAULT '',
  `status_id` int(11) NOT NULL DEFAULT 0,
  `url` varchar(255) DEFAULT '',
  `payment_details` mediumtext DEFAULT NULL,
  `ip` varchar(40) DEFAULT NULL,
  `undiscounted_total_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total_price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `note` varchar(1024) NOT NULL DEFAULT '',
  `separate_delivery` tinyint(1) DEFAULT 0,
  `modified` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `lang_id` int(11) NOT NULL DEFAULT 0,
  `referer_channel` enum('email','search','social','referral','unknown') DEFAULT NULL,
  `referer_source` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `login` (`user_id`),
  KEY `written_off` (`closed`),
  KEY `date` (`date`),
  KEY `status` (`status_id`),
  KEY `payment_status` (`paid`),
  KEY `code` (`url`(100)),
  KEY `phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


