  PRIMARY KEY (`id`),
  KEY `order_num` (`position`),
  KEY `url` (`url`(100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `ok_payment_methods`;
